import AppIntents
import Foundation
public struct PamIntentActionEntity:AppEntity{public static var typeDisplayRepresentation=TypeDisplayRepresentation(name:"PAM Native Action");public static var defaultQuery=PamIntentActionQuery();public let id:String;public let title:String;public let subtitle:String;public let deepLink:String;public var displayRepresentation:DisplayRepresentation{DisplayRepresentation(title:"\(title)",subtitle:"\(subtitle)")};public static func updateAppShortcutParameters(){}}
public struct PamIntentActionQuery:EntityQuery{public init(){};public func entities(for identifiers:[String])async throws->[PamIntentActionEntity]{actions().filter{identifiers.contains($0.id)}};public func suggestedEntities()async throws->[PamIntentActionEntity]{actions()};private func actions()->[PamIntentActionEntity]{let bundle=(Bundle.main.bundleIdentifier ?? "").replacingOccurrences(of:".intents",with:"");let defaults=UserDefaults(suiteName:"group.\(bundle).pam-native");return(defaults?.array(forKey:"pam.intent.actions")as?[[String:Any]] ?? []).compactMap{row in guard let id=row["id"]as?String,let title=row["title"]as?String,let deep=row["deepLink"]as?String else{return nil};return PamIntentActionEntity(id:id,title:title,subtitle:row["subtitle"]as?String ?? "",deepLink:deep)}}}
public struct OpenPamActionIntent:AppIntent{public static var title:LocalizedStringResource="Open PAM Native Action";public static var description=IntentDescription("Open a registered destination in your PAM Native app.");@Parameter(title:"Action")public var action:PamIntentActionEntity;public init(){};public init(action:PamIntentActionEntity){self.action=action};@MainActor public func perform()async throws->some IntentResult & OpensIntent{guard let url=URL(string:action.deepLink)else{throw PamIntentError.invalidURL};return.result(opensIntent:OpenURLIntent(url))}}
public struct PamAppShortcuts:AppShortcutsProvider{public static var appShortcuts:[AppShortcut]{AppShortcut(intent:OpenPamActionIntent(),phrases:["Open \(.applicationName)"],shortTitle:"Open Action",systemImageName:"arrow.up.forward.app")}}
private enum PamIntentError:Error{case invalidURL}
